var root="Assets/Visuals/Ships/Bulwark/";var p=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(root+"Bulwark Visual.prefab");var rows=new System.Collections.Generic.List<object>();foreach(var r in p.GetComponentsInChildren<UnityEngine.MeshRenderer>())foreach(var m in r.sharedMaterials){if(!m)throw new System.Exception("Missing material");if(UnityEditor.ShaderUtil.ShaderHasError(m.shader))throw new System.Exception(m.shader.name);rows.Add(new{renderer=r.name,material=UnityEditor.AssetDatabase.GetAssetPath(m),shader=m.shader.name});}var textures=new System.Collections.Generic.List<object>();foreach(var name in new[]{"Shadow","Light","Ink","DetailEmission","RegionWeights0"}){var i=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(root+"Paint/"+name+".png");if(i.sRGBTexture||i.textureCompression!=UnityEditor.TextureImporterCompression.Uncompressed)throw new System.Exception(name);textures.Add(new{name,linear=!i.sRGBTexture,compression=i.textureCompression.ToString(),mipmaps=i.mipmapEnabled});}return new{materials=rows,textures,shaderErrors=0};
